import {FIRST_JOBS,HOME_THEMES,CAR_COLORS,WHEEL_FINISHES,firstHourState,nextChapter,chapterInfo,cleanDecor} from './first-hour.mjs?v=38';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
export function createFirstHour(api){
 let state=firstHourState(),revision=0,loaded=false,error='',busy=false,draft=null,invitePath='',guest=null,queue=Promise.resolve(),lastHud='';
 const hud=document.createElement('button');hud.id='chapterButton';hud.className='chapter-button hidden';hud.onclick=()=>open();$('ui').appendChild(hud);
 async function request(path='',method='GET',body){const r=await fetch('/api/first-hour'+path,{method,credentials:'same-origin',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(10000)});const data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Your chapter could not be saved.'),{status:r.status});return data;}
 function apply(){api.design(guest?.decor||draft||state.decor,guest?guest.reward:state.reward);update();}
 async function load(){try{const data=await request();state=firstHourState(data.state);revision=data.revision;loaded=true;error='';apply();}catch(e){error=e.message;update();}}
 async function write(body){if(!loaded){await load();if(!loaded)throw Error(error||'Reconnect to save your chapter.');}try{const data=await request('','POST',{...body,revision});state=firstHourState(data.state);revision=data.revision;error='';apply();return state;}catch(e){error=e.message;if(e.status===409){await load();error=e.message;}update();throw e;}}
 function record(event){const task=queue.catch(()=>{}).then(()=>write({event}));queue=task;return task;}
 function update(){const mode=api.mode(),info=chapterInfo(state),key=[mode,loaded,error,JSON.stringify(state),!!guest].join('|');hud.classList.toggle('hidden',!['apartment','garage','driving'].includes(mode)||!!guest||api.testing());if(key===lastHud)return;lastHud=key;hud.innerHTML='<span>'+(error?'CHAPTER NEEDS ATTENTION':loaded?'FIRST CHAPTER · '+Math.min(3,state.completed)+' / 3 JOBS':'YOUR FIRST CHAPTER')+'</span><strong>'+esc(loaded?info[0]:'OPEN YOUR CHAPTER')+'</strong><small>OPEN JOURNAL →</small>';}
 async function action(fn,rerender=true){if(busy)return;busy=true;error='';try{await fn();}catch(e){error=e.message;api.notify(error);}finally{busy=false;if(rerender||$('lifeContinue'))open();else if(draft&&$('designSave'))renderDesigner();}}
 function open(){draft=null;apply();api.pause();const info=chapterInfo(state),phase=nextChapter(state);
  api.modal('<button class="modal-close" data-close aria-label="Close chapter">×</button><div class="life-journal"><span class="life-eyebrow">GETAWAY / CHAPTER ONE</span><h2 id="dialogTitle">MAKE YOURSELF AT HOME.</h2><p>A new set of keys. Three people to meet. A place that feels like yours.</p><ol class="life-steps">'+[['MOVE IN',state.movedIn],['CHOOSE YOUR RIDE',state.starter],['MEET THE NEIGHBORS',state.completed===3],['MAKE IT YOURS',state.decorated],['INVITE A FRIEND',state.invited]].map(([title,done],i)=>'<li class="'+(done?'done':'')+'"><b>'+(done?'✓':String(i+1).padStart(2,'0'))+'</b><span>'+title+'</span></li>').join('')+'</ol><div class="life-objective"><span>'+ (phase==='jobs'?'JOB '+(state.completed+1)+' OF 3':'YOUR NEXT STEP')+'</span><h3>'+esc(info[0])+'</h3><p>'+esc(info[1])+'</p></div>'+(error?'<p class="life-error" role="alert">'+esc(error)+'</p>':'')+'<button class="primary" id="lifeContinue" '+(busy?'disabled':'')+'>'+(busy?'SAVING…':!loaded?'LOAD MY CHAPTER':info[2])+'</button><div class="life-links"><button id="lifeDecor" class="small-btn">CUSTOMIZE HOME & CAR</button><button id="lifeOnline" class="small-btn">ONLINE NEIGHBORHOOD</button></div>'+(state.movedIn?'<button class="small-btn" id="lifeReplayArrival">REPLAY YOUR ARRIVAL · MEET JULES</button>':'')+(api.hasCasual()?'<button class="small-btn" id="lifeResumeCasual">RESUME YOUR EARLIER FREE SHIFT</button>':'')+'<p class="life-note">Chapter and designs save to your account. Driving shifts and arcade credits save on this browser.</p></div>',true);
  $('lifeContinue').onclick=()=>{if(!loaded){void action(load);return;}if(phase==='move'){api.close();api.arrival();}else if(phase==='starter'){api.close();api.garage();starter();}else if(phase==='jobs'){api.close();api.story(FIRST_JOBS[state.completed]);}else if(phase==='bank'){api.close();api.bankRoute();}else if(phase==='reward'){void action(async()=>{await record({type:'reward'});api.notify('HOUSEWARMING KIT UNLOCKED');customize();},false);}else if(phase==='invite')invite();else customize();};
  if($('lifeReplayArrival'))$('lifeReplayArrival').onclick=()=>{api.close();api.arrival();};
  if($('lifeResumeCasual'))$('lifeResumeCasual').onclick=api.resumeCasual;
  $('lifeDecor').onclick=customize;$('lifeOnline').onclick=api.online;
 }
 function starter(){api.pause();api.modal('<button class="modal-close" data-close aria-label="Close starter selection">×</button><span class="life-eyebrow">YOUR FIRST SET OF WHEELS / FREE</span><h2 id="dialogTitle">THE WORKHORSE.</h2><p>Three seats, a detailed interior, and enough room for your new crew. Choose its starting finish.</p><div class="life-starters">'+CAR_COLORS.slice(0,4).map((c,i)=>'<button data-starter="'+i+'"><img src="'+api.thumbnail(i)+'" alt="Workhorse in '+c.name+'"><strong>'+c.name+'</strong><span>FREE STARTER</span></button>').join('')+'</div><p class="life-note">You can change the finish later. Every garage car is also available for a free test drive.</p>',true);
  document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>{if(busy)return;void action(async()=>{await write({decor:{...state.decor,paint:Number(b.dataset.starter)}});await record({type:'starter'});api.equipStarter();api.close();api.notify('YOUR WORKHORSE IS READY');open();},false);});
 }
 function customize(){if(!loaded){open();return;}if(!['apartment','garage'].includes(api.mode()))api.home();draft={...state.decor};renderDesigner();}
 function choice(key,options){return '<div class="life-options">'+options.map(o=>{const id=typeof o==='string'?o:o.id,name=typeof o==='string'?o:o.name;return '<button data-design-key="'+key+'" data-design-value="'+id+'" aria-pressed="'+(String(draft[key])===String(id))+'">'+esc(name)+'</button>';}).join('')+'</div>';}
 function renderDesigner(){api.pause();api.modal('<button class="modal-close" id="designClose" aria-label="Cancel design">×</button><div class="life-designer"><span class="life-eyebrow">YOUR PLACE / LIVE PREVIEW</span><h2 id="dialogTitle">MAKE IT YOURS.</h2><div class="life-tabs"><button id="designHome" aria-pressed="'+(api.mode()==='apartment')+'">APARTMENT</button><button id="designGarage" aria-pressed="'+(api.mode()==='garage')+'">GARAGE & CAR</button></div><div class="life-design-scroll"><h3>ROOM PALETTE</h3>'+choice('theme',HOME_THEMES)+(api.mode()==='garage'?'<h3>GARAGE FLOOR</h3>'+choice('garageFloor',['teal','terracotta','midnight']):'<h3>FLOOR</h3>'+choice('floor',['oak','walnut','sand'])+'<h3>RUG</h3>'+choice('rug',['woven','stripe','none'])+'<h3>WALL ART</h3>'+choice('art',['city','records','botanical']))+'<h3>LIGHTING</h3>'+choice('lamp',['warm','mint','rose'])+'<h3>CAR PAINT</h3><div class="life-swatches">'+CAR_COLORS.map((c,i)=>'<button data-design-key="paint" data-design-value="'+i+'" style="--swatch:'+c.color+'" aria-label="'+c.name+' paint" aria-pressed="'+(draft.paint===i)+'"><span></span>'+c.name+'</button>').join('')+'</div><h3>WHEELS</h3>'+choice('wheels',WHEEL_FINISHES)+'<h3>HOUSEWARMING KIT '+(state.reward?'✓':'· LOCKED')+'</h3><div class="life-options"><button data-design-key="plants" data-design-value="'+!draft.plants+'" '+(!state.reward?'disabled':'')+'>PLANTERS '+(draft.plants?'ON':'OFF')+'</button><button data-design-key="underglow" data-design-value="'+!draft.underglow+'" '+(!state.reward?'disabled':'')+'>UNDERGLOW '+(draft.underglow?'ON':'OFF')+'</button></div>'+(!state.reward?'<p class="life-note">Finish your three story jobs and bank your haul to earn this kit.</p>':'')+'</div><p id="designStatus" role="status">Preview changes before saving.</p><button id="designSave" class="primary" '+(busy?'disabled':'')+'>SAVE MY DESIGN</button><button id="designCancel" class="small-btn">CANCEL CHANGES</button></div>',true);$('modalRoot').classList.add('life-design-shade');
  for(const b of document.querySelectorAll('[data-design-key]'))b.onclick=()=>{const k=b.dataset.designKey,v=b.dataset.designValue;draft[k]=k==='paint'?Number(v):['plants','underglow'].includes(k)?v==='true':v;apply();renderDesigner();};
  const cancel=()=>{draft=null;apply();api.close();};$('designClose').onclick=cancel;$('designCancel').onclick=cancel;
  $('designHome').onclick=()=>{const keep=draft;api.home();draft=keep;apply();renderDesigner();};$('designGarage').onclick=()=>{const keep=draft;api.garage();draft=keep;apply();renderDesigner();};
  $('designSave').onclick=async()=>{if(busy)return;busy=true;const chosen=cleanDecor(draft);$('designSave').disabled=true;$('designStatus').textContent='SAVING YOUR DESIGN…';try{await write({decor:chosen});draft=null;api.usePaint();apply();api.close();api.notify('YOUR DESIGN IS SAVED');}catch(e){$('designStatus').textContent=e.message;}finally{busy=false;if($('designSave'))$('designSave').disabled=false;}};
  apply();
 }
 function invite(){api.pause();api.modal('<button class="modal-close" data-close aria-label="Close invitation">×</button><span class="life-eyebrow">HOUSEWARMING / HOME TOUR</span><h2 id="dialogTitle">COME ON OVER.</h2><p>Let a friend walk through your saved apartment and garage design.</p><p>People with the link and access to this Site can take a personal tour. Meet each other in the online neighborhood for shared city driving.</p><label class="life-invite-label">YOUR HOME-TOUR LINK<input id="lifeInviteLink" readonly value="'+esc(invitePath?new URL(invitePath,location.origin).href:'')+'" placeholder="Create your invitation below"></label><p id="lifeInviteStatus" role="status"></p><button id="lifeCopyInvite" class="primary">'+(invitePath?'COPY INVITATION':'CREATE HOME INVITATION')+'</button><button id="lifeInviteDone" class="small-btn hidden">I COPIED THE LINK</button><div class="life-links"><a class="small-btn" href="/crew/">FRIENDS & CREW</a><button id="lifeRevoke" class="small-btn">CLOSE OLD INVITATIONS</button></div>',true);
  $('lifeCopyInvite').onclick=async()=>{if(busy)return;busy=true;try{if(!invitePath){const r=await request('/invite','POST',{});invitePath=r.path;}$('lifeInviteLink').value=new URL(invitePath,location.origin).href;try{await navigator.clipboard.writeText($('lifeInviteLink').value);await record({type:'invite'});$('lifeInviteStatus').textContent='COPIED · Send this link to your friend.';}catch{$('lifeInviteLink').select();$('lifeInviteDone').classList.remove('hidden');$('lifeInviteStatus').textContent='Select and copy your invitation, then send it to your friend.';}$('lifeCopyInvite').textContent='COPY INVITATION';}catch(e){$('lifeInviteStatus').textContent=e.message;}finally{busy=false;}};
  $('lifeInviteDone').onclick=async()=>{if(busy)return;busy=true;try{await record({type:'invite'});$('lifeInviteStatus').textContent='INVITATION READY · Send it to your friend.';$('lifeInviteDone').classList.add('hidden');}catch(e){$('lifeInviteStatus').textContent=e.message;}finally{busy=false;}};
  $('lifeRevoke').onclick=async()=>{if(busy)return;busy=true;try{await request('/invite','DELETE');invitePath='';$('lifeInviteLink').value='';$('lifeInviteStatus').textContent='Old invitations are closed.';$('lifeCopyInvite').textContent='CREATE HOME INVITATION';}catch(e){$('lifeInviteStatus').textContent=e.message;}finally{busy=false;}};
 }
 async function visit(token){try{guest=await request('/visit/'+encodeURIComponent(token));api.home();apply();api.guest(guest);}catch(e){api.notify(e.message);}}
 function leaveGuest(){guest=null;api.home();apply();}
 function closed(){if(draft){draft=null;apply();}}
 return{load,open,starter,customize,invite,record,update,apply,closed,visit,leaveGuest,get state(){return state;},get loaded(){return loaded;},get guest(){return guest;},get decor(){return guest?.decor||draft||state.decor;}};
}
